package org.apache.commons.math3.optimization.linear;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.exception.MaxCountExceededException;
import org.apache.commons.math3.optimization.PointValuePair;
import org.apache.commons.math3.util.Precision;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for SimplexSolver.solvePhase1.
 * Since solvePhase1 is protected, we use a subclass to expose it for testing.
 */
public class SimplexSolver_solvePhase1_TriageGen1Test {

    private TestableSimplexSolver solver;
    private SimplexTableau mockTableau;
    private static final double EPSILON = 1e-10;

    // Subclass to expose the protected method for testing
    private static class TestableSimplexSolver extends SimplexSolver {
        public TestableSimplexSolver() {
            super();
        }

        @Override
        public void solvePhase1(final SimplexTableau tableau) 
                throws MaxCountExceededException, UnboundedSolutionException, NoFeasibleSolutionException {
            super.solvePhase1(tableau);
        }

        // Override doIteration to control the loop behavior and avoid real heavy computation
        @Override
        protected void doIteration(final SimplexTableau tableau) 
                throws MaxCountExceededException, UnboundedSolutionException {
            super.doIteration(tableau);
        }
    }

    @Before
    public void setUp() {
        solver = new TestableSimplexSolver();
        mockTableau = mock(SimplexTableau.class);
    }

    /**
     * Tests the early return branch: when numArtificialVariables is 0.
     * Covers: if (tableau.getNumArtificialVariables() == 0) { return; }
     */
    @Test
    public void testSolvePhase1_NoArtificialVariables_ReturnsImmediately() throws Exception {
        when(mockTableau.getNumArtificialVariables()).thenReturn(0);

        solver.solvePhase1(mockTableau);

        verify(mockTableau, never()).isOptimal();
        verify(mockTableau, never()).getEntry(anyInt(), anyInt());
    }

    /**
     * Tests the successful Phase 1 completion.
     * Covers: while loop executes and W (objective value at index 0) is zero.
     */
    @Test
    public void testSolvePhase1_SuccessfulPhase1() throws Exception {
        // Setup: has artificial variables, not initially optimal, becomes optimal after 1 iteration
        when(mockTableau.getNumArtificialVariables()).thenReturn(1);
        when(mockTableau.isOptimal()).thenReturn(false, true);

        // Mock the tableau to behave like a real SimplexTableau for the final check
        // We need to mock getEntry(0, rhsOffset) to return 0.0
        int rhsOffset = 5;
        when(mockTableau.getRhsOffset()).thenReturn(rhsOffset);
        when(mockTableau.getEntry(0, rhsOffset)).thenReturn(0.0);

        // We need to spy on the solver to mock doIteration since it's protected and called internally
        TestableSimplexSolver spySolver = spy(solver);
        doNothing().when(spySolver).doIteration(mockTableau);

        spySolver.solvePhase1(mockTableau);

        verify(spySolver, times(1)).doIteration(mockTableau);
        verify(mockTableau, times(2)).isOptimal(); // one false, one true
    }

    /**
     * Tests the failure case where Phase 1 ends but the objective W is not zero.
     * Covers: if (!Precision.equals(tableau.getEntry(0, tableau.getRhsOffset()), 0d, epsilon)) { throw ... }
     */
    @Test(expected = NoFeasibleSolutionException.class)
    public void testSolvePhase1_NoFeasibleSolution() throws Exception {
        when(mockTableau.getNumArtificialVariables()).thenReturn(1);
        when(mockTableau.isOptimal()).thenReturn(true); // Loop skipped

        int rhsOffset = 5;
        when(mockTableau.getRhsOffset()).thenReturn(rhsOffset);
        // W is not zero (e.g., 0.5)
        when(mockTableau.getEntry(0, rhsOffset)).thenReturn(0.5);

        solver.solvePhase1(mockTableau);
    }

    /**
     * Tests that exceptions from doIteration are propagated.
     * Covers: MaxCountExceededException and UnboundedSolutionException
     */
    @Test(expected = MaxCountExceededException.class)
    public void testSolvePhase1_PropagatesMaxCountExceededException() throws Exception {
        when(mockTableau.getNumArtificialVariables()).thenReturn(1);
        when(mockTableau.isOptimal()).thenReturn(false);

        TestableSimplexSolver spySolver = spy(solver);
        doThrow(new MaxCountExceededException(100)).when(spySolver).doIteration(mockTableau);

        spySolver.solvePhase1(mockTableau);
    }

    @Test(expected = UnboundedSolutionException.class)
    public void testSolvePhase1_PropagatesUnboundedSolutionException() throws Exception {
        when(mockTableau.getNumArtificialVariables()).thenReturn(1);
        when(mockTableau.isOptimal()).thenReturn(false);

        TestableSimplexSolver spySolver = spy(solver);
        doThrow(new UnboundedSolutionException()).when(spySolver).doIteration(mockTableau);

        spySolver.solvePhase1(mockTableau);
    }
}
